@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class StayCategory {
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Stay {
  + StartDate : date
  + Status : string
}

class Registration {
  + RegistrationDate : date
  + BasicData : string
  + AssessmentResults : string
}

class Assessment {
  + AssessmentDate : date
  + Needs : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceDate : date
  + TotalAmount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" StayCategory
Inhabitant "1" -- "0..*" Stay
Stay "0..*" -- "1" StayCategory
Inhabitant "1" -- "1" Registration
Registration "1" -- "0..1" Assessment
Inhabitant "1" -- "0..*" WaitingList
WaitingList "0..*" -- "1" StayType
Inhabitant "1" -- "0..*" Proposal
Proposal "0..*" -- "1" StayType
Stay "1" -- "0..*" Invoice
Invoice "1" -- "0..1" CreditNote

@enduml

